// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    address player;

    function setUp() public {
        // deploy from an EOA so `bank` is a plain payable EOA (ETH transfers to it succeed)
        player = address(uint160(0xA11CE));
        vm.prank(player);
        c = new EtherLotto();
    }

    function testFuzz_property(uint256 seed) public {
        // admissible domain: any block timestamp (roll difficulty to a fixed admissible value)
        vm.roll(1);
        vm.warp(bound(seed, 1, type(uint64).max));

        // replicate the on-chain pseudo-random outcome from public chain state
        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;

        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();

        // RULE: after a completed round, the pot is 0 exactly when the outcome was 0
        // (payout round: fee to bank, prize to player, pot reset), and TICKET_AMOUNT otherwise.
        assertTrue((c.pot() == 0) == (random == 0));
    }
}
